local MillSailClothMaker = {}
local PRODUCTS = {
    iron_millsailcloth = { name = "Železni jedrna tkanina za mlin", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni jedrna tkanina za mlin za mlinarje." },
    bronze_millsailcloth = { name = "Bronast jedrna tkanina za mlin", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast jedrna tkanina za mlin za mlinarje." },
    silver_millsailcloth = { name = "Srebrn jedrna tkanina za mlin", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn jedrna tkanina za mlin za mlinarje." },
    gilded_millsailcloth = { name = "Pozlačen jedrna tkanina za mlin", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen jedrna tkanina za mlin za mlinarje." },
    jewel_set_millsailcloth = { name = "Draguljast jedrna tkanina za mlin", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast jedrna tkanina za mlin za mlinarje." },
    royal_sovereign_millsailcloth = { name = "Kraljevski suveren jedrna tkanina za mlin", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren jedrna tkanina za mlin z biseri za krono." },
}
local BUILDINGS = {
    millsailcloth_workshop = { name = "Millsailcloth delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    millsailcloth_house = { name = "Millsailcloth hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_millsailcloth_atelier = { name = "Mojstrski millsailcloth atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_millsailcloth_palace = { name = "Suverena millsailcloth palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
MillSailClothMaker.ironStock=10; MillSailClothMaker.bronzeStock=8; MillSailClothMaker.woodStock=16; MillSailClothMaker.leatherStock=14; MillSailClothMaker.silverStock=8; MillSailClothMaker.goldStock=6; MillSailClothMaker.jewelStock=4; MillSailClothMaker.pearlStock=4
MillSailClothMaker.productStock = {}; MillSailClothMaker.buildings = {}; MillSailClothMaker.maker = nil; MillSailClothMaker.activeMaking = {}; MillSailClothMaker.totalProducts = 0; MillSailClothMaker.dayTimer = 0
function MillSailClothMaker.init() MillSailClothMaker.ironStock=10; MillSailClothMaker.bronzeStock=8; MillSailClothMaker.woodStock=16; MillSailClothMaker.leatherStock=14; MillSailClothMaker.silverStock=8; MillSailClothMaker.goldStock=6; MillSailClothMaker.jewelStock=4; MillSailClothMaker.pearlStock=4; MillSailClothMaker.productStock={}; MillSailClothMaker.buildings={}; MillSailClothMaker.maker=nil; MillSailClothMaker.activeMaking={}; MillSailClothMaker.totalProducts=0; MillSailClothMaker.dayTimer=0; print("[MillSailClothMaker] Royal Mill Sail Cloth Maker System initialized (6 products, 4 buildings)") end
function MillSailClothMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MillSailClothMaker.maker={name=n or ("Tkalnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tkalnik najet: %s (spretnost: %d)",MillSailClothMaker.maker.name,s),"success") end; return true end
function MillSailClothMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MillSailClothMaker.build(id) local ok,e=MillSailClothMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MillSailClothMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MillSailClothMaker.getQualityBonus() local b=0; for _,bd in ipairs(MillSailClothMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MillSailClothMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MillSailClothMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MillSailClothMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MillSailClothMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MillSailClothMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MillSailClothMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MillSailClothMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MillSailClothMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MillSailClothMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MillSailClothMaker.buildings==0 then return false,"Potrebna tkalna delavnica" end; if not MillSailClothMaker.maker then return false,"Potreben tkalnik" end; return true end
function MillSailClothMaker.make(pt,qty) qty=qty or 1; local ok,e=MillSailClothMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MillSailClothMaker.ironStock=MillSailClothMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then MillSailClothMaker.bronzeStock=MillSailClothMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then MillSailClothMaker.woodStock=MillSailClothMaker.woodStock-d.woodCost*qty end; if d.leatherCost then MillSailClothMaker.leatherStock=MillSailClothMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then MillSailClothMaker.silverStock=MillSailClothMaker.silverStock-d.silverCost*qty end; if d.goldCost then MillSailClothMaker.goldStock=MillSailClothMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MillSailClothMaker.jewelStock=MillSailClothMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MillSailClothMaker.pearlStock=MillSailClothMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MillSailClothMaker.maker then t=math.max(1,t-math.floor(MillSailClothMaker.maker.skill/13)) end; table.insert(MillSailClothMaker.activeMaking,{id="millsailcloth_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MillSailClothMaker.completeMaking(m) local q=1.0+(MillSailClothMaker.getQualityBonus()/100); if MillSailClothMaker.maker then q=q+(MillSailClothMaker.maker.skill/140) end; q=math.min(2.5,q); MillSailClothMaker.productStock[m.productType]=(MillSailClothMaker.productStock[m.productType] or 0)+m.quantity; MillSailClothMaker.totalProducts=MillSailClothMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MillSailClothMaker.maker then MillSailClothMaker.maker.itemsMade=MillSailClothMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MillSailClothMaker.maker.skill=math.min(100,MillSailClothMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tkanina izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"millsailcloth.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function MillSailClothMaker.update(dt) if not _G.state then return end; MillSailClothMaker.dayTimer=MillSailClothMaker.dayTimer+dt; if MillSailClothMaker.dayTimer>=30 then MillSailClothMaker.dayTimer=0; for i=#MillSailClothMaker.activeMaking,1,-1 do local m=MillSailClothMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MillSailClothMaker.completeMaking(m); table.remove(MillSailClothMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MillSailClothMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MillSailClothMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MillSailClothMaker.getStats() return {ironStock=MillSailClothMaker.ironStock,bronzeStock=MillSailClothMaker.bronzeStock,woodStock=MillSailClothMaker.woodStock,leatherStock=MillSailClothMaker.leatherStock,silverStock=MillSailClothMaker.silverStock,goldStock=MillSailClothMaker.goldStock,jewelStock=MillSailClothMaker.jewelStock,pearlStock=MillSailClothMaker.pearlStock,productStock=MillSailClothMaker.productStock,numBuildings=#MillSailClothMaker.buildings,hasMaker=MillSailClothMaker.maker~=nil,makerName=MillSailClothMaker.maker and MillSailClothMaker.maker.name or "—",makerSkill=MillSailClothMaker.maker and MillSailClothMaker.maker.skill or 0,activeMaking=#MillSailClothMaker.activeMaking,totalProducts=MillSailClothMaker.totalProducts} end
return MillSailClothMaker
